// clang-format on

RandoCheckId GetCheckByPosition(int32_t posX, int32_t posY, int32_t posZ) {
    for (auto& [randoCheckId, randoStaticCheck] : Checks) {
        if (randoStaticCheck.posX == posX && randoStaticCheck.posY == posY && randoStaticCheck.posZ == posZ) {
            return randoCheckId;
        }
    }

    for (auto& [checkId, spawnPos] : multiSpawnCheckMap) {
        if (std::get<0>(spawnPos) == posX && std::get<1>(spawnPos) == posY && std::get<2>(spawnPos) == posZ) {
            return checkId;
        }
    }

    return RC_UNKNOWN;
}

RandoCheckId GetCheckByMumboTokenId(mumbotoken_e tokenId) {
    for (auto& [randoCheckId, randoStaticCheck] : Checks) {
        if (randoStaticCheck.randoCheckType != RCTYPE_MUMBO_TOKEN) {
            continue;
        }

        if (randoStaticCheck.collectionId == tokenId) {
            return randoCheckId;
        }
    }

    return RC_UNKNOWN;
}

RandoCheckId GetCheckByHoneycombId(honeycomb_e honeycombId) {
    for (auto& [randoCheckId, randoStaticCheck] : Checks) {
        if (randoStaticCheck.randoCheckType != RCTYPE_EMPTY_HONEYCOMB) {
            continue;
        }

        if (randoStaticCheck.collectionId == honeycombId) {
            return randoCheckId;
        }
    }

    return RC_UNKNOWN;
}

RandoCheckId GetCheckByJiggyId(int32_t jiggyId) {
    for (auto& [randoCheckId, randoStaticCheck] : Checks) {
        if (randoStaticCheck.randoCheckType != RCTYPE_JIGGY) {
            continue;
        }

        if (randoStaticCheck.collectionId == jiggyId) {
            return randoCheckId;
        }
    }

    return RC_UNKNOWN;
}

RandoCheckId GetJinjoJiggyCheckByLevelId(int16_t levelId) {
    for (auto& [randoCheckId, randoStaticCheck] : Checks) {
        if (randoStaticCheck.randoCheckType != RCTYPE_JIGGY) {
            continue;
        }

        if (randoStaticCheck.collectionId == (10 * levelId) - 9) {
            return randoCheckId;
        }
    }

    return RC_UNKNOWN;
}

RandoCheckId GetCheckByAbilityId(int32_t abilityId) {
    for (auto& [randoCheckId, randoStaticCheck] : Checks) {
        if (randoStaticCheck.randoCheckType != RCTYPE_MOLEHILL) {
            continue;
        }

        if (randoStaticCheck.collectionId == abilityId) {
            return randoCheckId;
        }
    }

    return RC_UNKNOWN;
}

